    IGUI_Tutorial1_Welcome1 = " <CENTRE> <SIZE:large> Bem-vindo ao Project Zomboid! <LINE> <LINE> <SIZE:medium> Em breve, você morrerá horrivelmente. Ninguém vai chorar por você, e você será rapidamente esquecido. Tudo terá sido em vão!<LINE> <LINE> Então vamos garantir que você saia lutando!",
    IGUI_Tutorial1_Welcome2 = " <CENTRE> <SIZE:medium> Primeiro o essencial: você pode dar zoom com a roda do mouse ou com as teclas %1/%2. <LINE> <LINE> Vamos ter uma visão panorâmica do lugar solitário onde você está prestes a morrer - miserável e sozinho! <LINE> <LINE> <SIZE:large> Dê um zoom para longe!",
    IGUI_Tutorial1_Welcome3 = " <CENTRE> <SIZE:medium> Você é ótimo nisso! <LINE> <LINE> Vamos dar uma olhada nas informações do seu personagem. <LINE> <LINE> <SIZE:large> Clique no Coração que está piscando à esquerda!",
    IGUI_Tutorial1_Welcome4 = " <CENTRE> <SIZE:medium> Aqui você pode ver seu Estado de Saúde. <LINE> <LINE> Arranhões, mordidas, sangramento, fraturas: tudo mostrado aqui para sua conveniência! <LINE> <LINE> Também é aqui que você poderá se curar e tratar os ferimentos.",
    IGUI_Tutorial1_Welcome5 = " <CENTRE> <SIZE:medium> Você sabia que há um outro painel excelente? Sim! O Painel de Habilidades! <LINE> <LINE> <SIZE:large> Clique na aba de Habilidades por favor!",
    IGUI_Tutorial1_Welcome6 = " <CENTRE> <SIZE:medium> Demais! Realmente será UMA PENA perder você! <LINE> <LINE> Este painel mostra seus pontos em várias habilidades de sobrevivência diferentes.",
    IGUI_Tutorial1_Welcome7 = " <CENTRE> <SIZE:medium> Diversas ações no jogo acumulam Pontos de Habilidade que aumentam seu nível em cada habilidade. <LINE> <LINE> Sua velocidade de aprendizado pode ser aumentada através da leitura de livros e ao assistir certos programas de TV! <LINE> <LINE> Em última análise, seu cérebro se tornará uma gosma fria e morta - mas, enquanto isso, por que não aprender Carpintaria?",
    IGUI_Tutorial1_Welcome8 = " <CENTRE> <SIZE:medium> Hora de tirar essas rodinhas, querida! <LINE> <LINE> <SIZE:large> Feche o Painel do Personagem clicando no X, e avançaremos para o próximo empolgante aspecto da vida de um sobrevivente!",
    IGUI_Tutorial1_Welcome9 = " <CENTRE> <SIZE:medium> Que é... observar as coisas! Uau! <LINE> <LINE> Mantenha pressionado o Botão Direito do Mouse e mova-o. <LINE> <LINE> <SIZE:large> Você poderá virar para QUALQUER ângulo! (Segurando o CTRL e movendo o mouse também fará isso!)",
    IGUI_Tutorial1_Welcome10 = " <CENTRE> <SIZE:medium> PLOT TWIST! <LINE> <LINE> Você só consegue ver para a direção em que está olhando! <LINE> <LINE> Uma morte rápida e inesperada pode vir de trás: seja de um morto-vivo ou de seu companheiro!",
    IGUI_Tutorial1_Welcome2bis = " <CENTRE> <SIZE:medium> Agora, dê o zoom de volta!",
    IGUI_Tutorial1_MovementKeys = "%1 / %2 / %3 / %4",
    IGUI_Tutorial1_WalkTo1 = " <CENTRE> <SIZE:medium> Vamos bombear esse sangue, antes que congele e apodreça! <LINE> <LINE> Mova-se com as teclas %1. <LINE> <LINE> <SIZE:large> Por que não entrar na sala ao lado? Com certeza está segura!",
    IGUI_Tutorial1_WalkTo2 = " <CENTRE> <SIZE:medium> Viu! Eu disse que era segura! <LINE> <LINE> Agora vamos nos mexer! Segurando o Botão Direito do Mouse permitirá que você olhe ao redor enquanto caminha. <LINE> Isso o ajudará a alinhar os ataques e olhar para trás. <LINE> <LINE> <SIZE:large> Avance mais pela sala segurando o Botão Direito do Mouse e movendo-se usando %1! ",
    IGUI_Tutorial1_WalkTo3 = " <CENTRE> <SIZE:medium> Pessoa morta a frente! <LINE> <LINE> Você precisará de alguns recursos se quer sobreviver a um ataque! <LINE> <LINE> <SIZE:large> Volte para o balcão marcado na cozinha e aprenderemos a lootear!",
    IGUI_Tutorial1_InvLoot1 = " <CENTRE> <SIZE:medium> A fome pode ser saciada looteando as casas dos recém-falecidos! <LINE> <LINE> <SIZE:large> Mova o mouse sobre o Painel de Loot e expanda-o.",
    IGUI_Tutorial1_InvLoot2 = " <CENTRE> <SIZE:large> Um rato morto! <SIZE:medium> <LINE> <LINE> <SIZE:large> Para pegá-lo, clique duas vezes! ",
    IGUI_Tutorial1_InvLoot3 = " <CENTRE> <SIZE:medium> Provavelmente deveríamos pegar aquela Garrafa Vazia também. Morrer de sede é horrível. <LINE> <LINE> <SIZE:large> Clique duas vezes na Garrafa Vazia!",
    IGUI_Tutorial1_InvUse1 = " <CENTRE> <SIZE:medium> Consegue ver os status à direita? <LINE> Parece que alguém está com a barriga roncando. Hora de comer! <LINE> <LINE> <SIZE:large> Clique com o Botão Direito do Mouse no rato morto e terá opções de interação. <LINE> <LINE> <SIZE:large> Coma o rato morto!",
    IGUI_Tutorial1_InvUse2 = " <CENTRE> <SIZE:medium> Bem melhor! Tirando a náusea... <LINE> <LINE> <SIZE:medium> Para aprender o que cada Humor significa, mova o cursor sobre eles!",
    IGUI_Tutorial1_InvUse2Bis = " <CENTRE> <SIZE:medium> Ah! Vamos encher sua garrafa de água antes que a água seja cortada. <LINE> <LINE> Clicando com o Botão Direito nos itens do mundo também terá opções de interação! <LINE> <LINE> <SIZE:large> Mova-se próximo à pia e clique com o Botão Direito para encher a garrafa.",
    IGUI_Tutorial1_InvUse3 = " <CENTRE> <SIZE:medium> Você bebe automaticamente da água que está no seu inventário principal. <LINE> <LINE> Vamos ver o que há nos outros armários! <LINE> <LINE> <SIZE:large> Abra o incrível Painel de Loot novamente!",
    IGUI_Tutorial1_InvUse4 = " <CENTRE> <SIZE:medium> Você pode olhar em recipientes próximos caminhando perto deles com o Painel de Loot aberto. <LINE> <LINE> Cada recipiente ao alcance pode ser aberto com um clique no Botão Esquerdo nos ícones do recipiente destacado. <LINE> <LINE> Convenientemente, há uma arma escondida para você por perto! <LINE> <LINE> <SIZE:large> Procure nos recipientes ao redor para encontrar uma arma!",
    IGUI_Tutorial1_InvUse5 = " <CENTRE> <SIZE:medium> Bem, é quase uma arma! <LINE> <LINE> <SIZE:large> Clique com o Botão Direito na Frigideira e selecione 'Equipar na Mão Principal' para que você possa usá-la contra todos os mortos-vivos que encontrar!",
    IGUI_Tutorial1_InvUse6 = " <CENTRE> <SIZE:medium> Tudo, por favor. Não temos tempo para isso.",
    IGUI_Tutorial1_InvUse7 = " <CENTRE> <SIZE:medium> Não. Tudo mesmo. <LINE> <LINE> Não tente ser espertinho. Há muitos outros como você.",
    IGUI_Tutorial1_Fight1 = " <CENTRE> <SIZE:medium> Minha nossa! Está ficando quente aqui? <LINE> <LINE> Vamos abrir a janela e tomar um pouco de ar fresco enquanto seu pulmão ainda é capaz! <LINE> <LINE> <SIZE:large> Caminhe até a janela piscando atrás de você! ",
    IGUI_Tutorial1_Fight2 = " <CENTRE> <SIZE:medium> Um zumbi com chapéu! <LINE> <LINE>Vamos lá! Pressionando %1 irá interagir com objetos a sua frente. Precisamente: portas e janelas! <LINE> <LINE> <SIZE:large> Pressione %1 para abrir a janela! ",
    IGUI_Tutorial1_Fight3 = " <CENTRE> <SIZE:medium> Saia pela janela e bata naquele cadáver de volta para a morte! <LINE> <LINE> <SIZE:large> Espere %1 Subir pela janela! ",
    IGUI_Tutorial1_Fight3Bis = " <CENTRE> <SIZE:medium> Você fez ERRADO! <LINE> <LINE> NÃO saia da linha. Para abrir ou fechar uma janela pressione '%1'. Para pulá-la você deve SEGURAR '%1'. <LINE> <LINE> <SIZE:large> Pressione \"%1\" para reabrir a janela, antes de considerarmos o término dessa etapa de aprendizado.",
    IGUI_Tutorial1_Fight4 = " <CENTRE> <SIZE:medium> Ela não nos viu! <LINE> <LINE> Segurar o Botão Direito do Mouse preparará sua arma para um ataque. Um Cursor Isométrico é exibido para ajudá-lo a avaliar seu ângulo de ataque! <LINE> <LINE> <SIZE:large> Segure o Botão Direito do Mouse!",
    IGUI_Tutorial1_Fight5 = " <CENTRE> <SIZE:medium> Segure o Botão Direito do Mouse e mova-se usando %1 para chegar perto da fétida mulher de chapéu! <LINE> <LINE> Clique com o Botão Esquerdo do Mouse para atacar quando estiver pronto! <LINE> <LINE> <SIZE:large> Lembre-se: segure o Botão Direito do Mouse para preparar a Frigideira, e clique com o Botão Esquerdo para atacar!",
    IGUI_Tutorial1_Fight7 = " <CENTRE> <SIZE:medium> Toma essa Mamãe! <LINE> <LINE> Você também poderia ter pressionado %1 para empurrá-la, mas agora precisamos acertar a cabeça! <LINE> <LINE> O Cursor Isométrico é VITAL para isso.",
    IGUI_Tutorial1_Fight7B = " <CENTRE> <SIZE:medium> O Cursor Isométrico mostra a posição do seu mouse em relação ao chão. <LINE> <LINE> <SIZE:large> Alinhe-se usando o Botão Direito do Mouse, e use o círculo na parte inferior do Cursor Isométrico para mirar na cabeça! Bata com o Botão Esquerdo do Mouse quando estiver no lugar!",
    IGUI_Tutorial1_Fight8New = " <CENTRE> <SIZE:medium> A Frigideira quebrou! O crânio da sua mãe era muito resistente! <LINE> <LINE> <SIZE:large> Vamos pegar emprestada a Faca de Caça que enfiamos nas costas dela antes! <LINE> <LINE> <SIZE:large> Pegue e equipe a Faca de Caça do corpo de sua mãe! Clique com o Botão Direito na Faca de Caça no Painel de Loot para mostrar as opções de Equipamento!",
    IGUI_Tutorial1_Sneak1 = " <CENTRE> <SIZE:medium> Você ouviu isso? Tem mais! <LINE> <LINE> Mova-se até o portão na cerca alta! <LINE> <LINE> <SIZE:large> Pressione %1 para abrir o portão ou clique nele com o Botão Esquerdo do Mouse quando estiver perto!",
    IGUI_Tutorial1_Sneak1Bis = " <CENTRE> <SIZE:medium> Morto-vivo vegetativo na horta! Mas ele tem função cerebral suficiente para ver você! <LINE> <LINE> Se você for furtivo, fará menos barulho, e será menos visível. <LINE> <LINE> <SIZE:large> Pressione %1 para agachar e mova-se furtivamente!",
    IGUI_Tutorial1_Sneak2 = " <CENTRE> <SIZE:medium> Uau! É como se estivesse invisível! Quer dizer, nós exageramos suas habilidades aqui - mas isso É impressionante. <LINE> <LINE> Ao se mover furtivamente perto de uma parede, cerca ou veículo, será mais discreto e reduzirá sua visibilidade ainda MAIS. <LINE> <LINE> <SIZE:large> Mova-se furtivamente ao virar da esquina para o portão abaixo na cerca.",
    IGUI_Tutorial1_Sneak2Bis = " <CENTRE> <SIZE:medium> Faça como solicitamos. Isso é perder tempo e dinheiro. <LINE> <LINE> Pressione %1 para agachar. Fique perto da cerca para se agachar automaticamente. <LINE> <LINE> <SIZE:large> Mova-se furtivamente para o portão na cerca. Agora.",
    IGUI_Tutorial1_Sneak3 = " <CENTRE> <SIZE:medium> Tão silencioso e tão mortal! Como um ninja condenado! <LINE> <LINE> <SIZE:large> Fique agachado e abra o portão com %1, ou clique nele com o Botão Esquerdo do Mouse quando estiver perto!",
    IGUI_Tutorial1_Sneak4 = " <CENTRE> <SIZE:medium> Isso aqui é coisa de Forças Especiais! <LINE> <LINE> Caminhe atrás dele com a faca! Seu braço irá levantar para mostrar que você está pronto para um ataque furtivo! <LINE> <LINE> <SIZE:large> Aproxime-se segurando o Botão Direito do Mouse, e ataque com um clique no Botão Esquerdo quando estiver diretamente atrás! Chegue perto com calma!",
    IGUI_Tutorial1_Sneak4Bis = " <CENTRE> <SIZE:medium> Boa tentativa, mas você precisa se aproximar! Quando estiver ao alcance, seu braço esquerdo se levantará! <LINE> <LINE> <SIZE:large> Aproxime-se segurando o Botão Direito do Mouse e ataque com um clique no Botão Esquerdo quando estiver diretamente atrás!",
    IGUI_Tutorial1_Sneak5 = " <CENTRE> <SIZE:medium> Você conseguiu! Chega de problemas com o Papai! <LINE> <LINE> Agora pegue a mochila dele e coloque-a em você. <LINE> <LINE> <SIZE:large> Certifique-se de estar sobre o cadáver e clique com o Botão Direito na Mochila Grande no Painel de Loot para mostrar as opções de interação.",
    IGUI_Tutorial1_Sneak6 = " <CENTRE> <SIZE:medium> Você queria esta Mochila Grande há anos, e agora ela é sua! <LINE> <LINE> Vamos ver o que tem dentro! <LINE> <LINE> <SIZE:large> Encontre o ícone da Mochila Grande piscando ao lado do Painel de Inventário. Clique nele!",
    IGUI_Tutorial1_Sneak7 = " <CENTRE> <SIZE:medium> Uma espingarda carregada e algumas bandagens! <LINE> Sempre fazemos o nosso melhor por você. Equipe-a com as duas mãos! <LINE> <LINE> <SIZE:large> Clique com o Botão Direito na espingarda para mostrar as opções de interação.",
    IGUI_Tutorial1_Bandage1 = " <CENTRE> <SIZE:medium> A janela da oficina do Papai quebrou, bem na hora! <LINE> Salte a cerca e vamos dar uma olhada! Correr para a cerca fará você saltá-la automaticamente. <LINE> <LINE> <SIZE:large> Corra usando %1 e %2 em direção à cerca!",
    IGUI_Tutorial1_Bandage2 = " <CENTRE> <SIZE:medium> Papai era um sobrevivencialista, mas ele não se preparou para você, não é mesmo? <LINE> <LINE> Vamos pegar seu equipamento! Ignore os cacos de vidro! <LINE> <LINE> <SIZE:large> Pule pela janela quebrada ficando próximo a ela e segurando %1.",
    IGUI_Tutorial1_Bandage2Bis = " <CENTRE> <SIZE:medium> INSOLÊNCIA! Essa NÃO era a cerca que dissemos para você saltar! <LINE> <LINE> Vamos continuar, de qualquer maneira. Há uma janela quebrada no galpão além da horta. <LINE> <LINE> <SIZE:large> Pule-a segurando %1.",
    IGUI_Tutorial1_Bandage3 = " <CENTRE> <SIZE:medium> Ah não! Suas mãos estão sangrando! O vidro quebrado na janela as cortaram. Quem poderia imaginar? <LINE> <LINE> <SIZE:large> Abra o Painel de Saúde pressionando %1, ou clicando no Ícone do Coração.",
    IGUI_Tutorial1_Bandage4 = " <CENTRE> <SIZE:medium> As bandagens da mochila vão ajudar! <LINE> <LINE> <SIZE:large> Clique com o Botão Direito do Mouse no texto em vermelho que indica a ferida na mão esquerda, e aplique um curativo.",
    IGUI_Tutorial1_Bandage5 = " <CENTRE> <SIZE:medium> Vamos verificar lá fora, caso haja mais autômatos de carne em decomposição! <LINE> <LINE> <SIZE:large> Vá para a janela com cortinas!",
    IGUI_Tutorial1_Bandage6 = " <CENTRE> <SIZE:medium> As cortinas impedem que você veja do lado de fora, mas também impedem que a horda veja o lado de dentro! <LINE> <LINE> Abra a cortina, provavelmente é seguro. <LINE> <LINE> <SIZE:large> Botão Direito do Mouse para interagir ou segure Shift Esquerdo e clique com o Botão Esquerdo na cortina!",
    IGUI_Tutorial1_Bandage7 = " <CENTRE> <SIZE:medium> Dois deles! <LINE> Três se você contar a sua irmã no chão! <LINE> <LINE> Melhor obter alguma proteção aprimorada contra suas unhas e dentes!",
    IGUI_Tutorial1_Bandage8 = " <CENTRE> <SIZE:medium> Roupas e chapéus mais grossos ajudam a proteger contra mordidas e arranhões. <LINE> <LINE> Vista o que achar melhor para um encontro final! <LINE> <LINE> <SIZE:large> Quando estiver pronto, passe pela porta!",
    IGUI_Tutorial1_Shotgun1 = " <CENTRE> <SIZE:medium> Lembre-se que você pode ser furtivo para fazer menos barulho. <LINE> <LINE> <SIZE:large> Pressione %1 para se agachar e vá até a cerca com arame.",
    IGUI_Tutorial1_Shotgun1b = " <CENTRE> <SIZE:medium> Se você tem habilidade o suficiente, e não estiver cansado, cercas altas podem ser escaladas! <LINE> <LINE> Você tem essa habilidade! <LINE> <LINE> <SIZE:large> Pressione %1 para pular a cerca de arame!",
    IGUI_Tutorial1_Shotgun2 = " <CENTRE> <SIZE:medium> Tão atlético! É hora de fazer barulho! <LINE> <LINE> Prepare a espingarda! <LINE> <LINE> <SIZE:large> Mire nos mortos-vivos segurando o Botão Direito do Mouse!",
    IGUI_Tutorial1_Shotgun3 = " <CENTRE> <SIZE:medium> Aí vem eles! <LINE> <LINE> <GHC> Um contorno verde mostra uma boa chance de sucesso com o alvo! <RGB:1,1,1> <LINE> <LINE> <SIZE:large> Pressione o Botão Esquerdo do Mouse para disparar enquanto mira com o Botão Direito do Mouse!",
    IGUI_Tutorial1_Shotgun4 = " <CENTRE> <SIZE:medium> Estão todos mortos! Que pena! <LINE> <LINE> Não importa, logo vocês estarão juntos novamente! <LINE> <LINE> Cada zumbi na floresta ouviu a espingarda, e eles estão vindo atrás de você! <LINE> <LINE> <SIZE:large> Pressione %1 para pular a cerca de arame e escapar!",
    IGUI_Tutorial1_Shotgun5 = " <CENTRE> <SIZE:medium> Eles estão se aproximando! <LINE> <LINE> Você sabe como correr, mas agora aprenderá como CORRER MAIS RÁPIDO!! Corra depressa para o marcador perto da casinha! Agora! <LINE> <LINE> <SIZE:large> Pressione %1 para mover-se e pressione %2 que alternará para CORRER RÁPIDO!",
    IGUI_Tutorial1_Shotgun5a = " <CENTRE> <SIZE:medium> Eles estão se aproximando! <LINE> <LINE> Você sabe como correr, mas agora aprenderá como CORRER MAIS RÁPIDO!! Corra depressa para o marcador perto da casinha! Agora! <LINE> <LINE> <SIZE:large> Pressione %1 para mover-se e aperte duas vezes %2 para CORRER RÁPIDO!",
    IGUI_Tutorial1_Shotgun6 = " <CENTRE> <SIZE:medium> Último conselho! Se você receber uma mordida de zumbi ou temer que o fim seja iminente, pressione '%1' e você engolirá o antídoto! <LINE> <LINE> <SIZE:large> Pressione %1 para tomar o antídoto!",
    IGUI_Tutorial1_Shotgun7 = " <CENTRE> <SIZE:medium> Brincadeirinha! <LINE> <LINE> Toda esperança se foi. Não há antídoto. <LINE> <LINE> <SIZE:large> Divirta-se! ",
    IGUI_Tutorial1_Shotgun8 = " <CENTRE> <SIZE:medium> Você morreu! <LINE> <LINE> Para mais ajuda no jogo principal, pressione %1 para abrir o Guia de Sobrevivência. <LINE> <LINE> <SIZE:large> Retorne ao Menu Principal e sobreviva ao verdadeiro Evento de Knox!",
    IGUI_Tutorial1_Welcome2Joypad = " <SIZE:medium> Primeiro o essencial: você pode dar zoom! <LINE> <JOYPAD:Back,28,28> Vai ativar um menu com várias funcionalidades. <LINE> <LINE> Vamos ter uma visão panorâmica do lugar solitário onde você está prestes a morrer - miserável e sozinho! <LINE> <SIZE:large> Segure <JOYPAD:Back,28,28> então selecione <IMAGE:media/ui/ZoomOut.png,28,28> com <JOYPAD:RStick,28,28>, e finalmente solte <JOYPAD:Back,28,28>.",
    IGUI_Tutorial1_Welcome3Joypad = " <SIZE:medium> Primeiro o essencial: <JOYPAD:Back,28,28> te levará a vários recursos impressionantes! <LINE> <LINE> Vamos dar uma olhada nas informações do seu personagem. <LINE> <SIZE:large> Segure <JOYPAD:Back,28,28> então selecione <IMAGE:media/ui/Heart2_On.png,32,32> com <JOYPAD:RStick,28,28>. Solte <JOYPAD:Back,28,28> e você está lá! <LINE> ",
    IGUI_Tutorial1_Welcome5Joypad = " <SIZE:medium> Você sabia que há um outro painel excelente? Sim! O Painel de Habilidades! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:LBumper,28,28> para interagir entre os painéis e verificar suas habilidades!",
    IGUI_Tutorial1_Welcome8Joypad = " <SIZE:medium> Hora de tirar essas rodinhas, querida! <LINE> <LINE> <SIZE:medium> Feche o Painel do Personagem pressionando <JOYPAD:BButton,28,28> e avançaremos para o próximo empolgante aspecto da vida de um sobrevivente!",
    IGUI_Tutorial1_Welcome9Joypad = " <SIZE:medium> Que é... observar as coisas! Uau! <LINE> <LINE> Movendo <JOYPAD:RStick,28,28> Você poderá virar para QUALQUER ângulo! <LINE> <LINE> Tente!",
    IGUI_Tutorial1_Welcome2bisJoypad = " <SIZE:medium> Agora, dê o zoom de volta! <LINE> <LINE> <SIZE:large> Abra novamente o menu com <JOYPAD:Back,28,28>, mas dessa vez selecione <IMAGE:media/ui/ZoomIn.png,32,32> <LINE> ",
    IGUI_Tutorial1_WalkTo1Joypad = "<SIZE:medium> Vamos bombear esse sangue, antes que congele e apodreça! <LINE> <LINE> Mova-se com <JOYPAD:LStick,28,28>. <LINE> <LINE> <SIZE:large> Por que não entrar na sala ao lado? Com certeza está segura!",
    IGUI_Tutorial1_WalkTo2Joypad = " <SIZE:medium>Viu! Eu disse que era segura! Agora vamos nos mexer! <LINE> <LINE> Segurando <JOYPAD:RStick,28,28> permitirá que você olhe ao redor enquanto caminha. Isso o ajudará a alinhar os ataques e olhar para trás. <LINE> <LINE> <SIZE:large> Aproxime-se do piano segurando <JOYPAD:RStick,28,28> e movendo-se usando <JOYPAD:LStick,28,28>.",
    IGUI_Tutorial1_InvLoot1Joypad = " <SIZE:medium> Pressionando <JOYPAD:YButton,28,28> abrirá seu Inventário e o Painel de Loot! <LINE> <LINE> <SIZE:large> Faça isso agora! Pressione <JOYPAD:YButton,28,28> !",
    IGUI_Tutorial1_InvLoot2Joypad = " <SIZE:medium> Você está vendo aqueles recipientes piscando à direita do Painel de Loot? Eles são todos os recipientes que poderá lootear nas proximidades. <LINE> <LINE> Pressione <JOYPAD:RBumper,28,28> para alternar entre com os recipientes!",
    IGUI_Tutorial1_InvLoot3Joypad = " <SIZE:large> Um rato morto! <SIZE:medium> <LINE> <LINE> <SIZE:large> Para pegá-lo, pressione <JOYPAD:XButton,28,28>.",
    IGUI_Tutorial1_InvLoot4Joypad = " <SIZE:medium> Provavelmente deveríamos pegar aquela garrafa vazia também. Morrer de sede é horrível. <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:XButton,28,28> para pegá-la!",
    IGUI_Tutorial1_InvUse1Joypad = " <SIZE:medium> Consegue ver os status à direita? <LINE> Parece que alguém está com a barriga roncando. Hora de comer! <LINE> <LINE> <SIZE:large> Primeiramente, pressione <JOYPAD:DPadLeft,28,28> para selecionar seu inventário!",
    IGUI_Tutorial1_InvUse1BisJoypad = " <SIZE:medium> Perfeito, pressione <JOYPAD:AButton,28,28> no rato morto em seu inventário para ver opções de interação! <LINE> <LINE> <SIZE:large> Selecione Comer, então Tudo e pressione <JOYPAD:AButton,28,28> para comer o rato morto!",
    IGUI_Tutorial1_InvUse2Joypad = " <CENTRE> <SIZE:medium> Bem melhor! Tirando a náusea... ",
    IGUI_Tutorial1_InvUse2BisJoypad = " <SIZE:medium> Ah! Vamos encher sua garrafa de água antes que a água seja cortada. <LINE> <LINE> Pressionando <JOYPAD:XButton,28,28> nos itens do mundo também terá opções de interação! <LINE> <LINE> <SIZE:large> Mova-se próximo à pia e pressione <JOYPAD:XButton,28,28> então selecione Encher Garrafa e confirme com <JOYPAD:AButton,28,28>.",
    IGUI_Tutorial1_InvUse3Joypad = " <CENTRE> <SIZE:medium> Você bebe automaticamente da água que está no seu inventário principal. <LINE> <LINE> Vamos ver o que há nos outros armários! <LINE> <LINE> <SIZE:large> Vamos para aquele recipiente destacado!",
    IGUI_Tutorial1_InvUse3BisJoypad = " <SIZE:medium> Agora pressione <JOYPAD:YButton,28,28> para abrir seu Painel de Loot.",
    IGUI_Tutorial1_InvUse4Joypad = " <SIZE:medium> Você pode ver os recipientes próximos caminhando perto deles <LINE> Cada recipiente ao alcance pode ser aberto com <JOYPAD:RBumper,28,28> <LINE> <LINE> Convenientemente, há uma arma escondida para você por perto! <LINE> <LINE> <SIZE:large> Procure nos recipientes ao redor para encontrar uma arma!",
    IGUI_Tutorial1_InvUse5Joypad = " <SIZE:medium> Bem, é quase uma arma! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:AButton,28,28> na Frigideira e selecione 'Equipar na Mão Principal' para que você possa usá-la contra todos os mortos-vivos que encontrar!",
    IGUI_Tutorial1_Fight2Joypad = " <SIZE:medium> Um zumbi com chapéu! <LINE> <LINE> Vamos lá! Pressionando <JOYPAD:AButton,28,28> irá interagir com objetos a sua frente. Precisamente: portas e janelas! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:AButton,28,28> para abrir a janela! ",
    IGUI_Tutorial1_Fight3Joypad = " <SIZE:medium> Saia pela janela e bata naquele cadáver de volta para a morte! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:BButton,28,28> Subir pela janela! ",
    IGUI_Tutorial1_Fight3BisJoypad = " <SIZE:medium> Você fez ERRADO. <LINE> <LINE> NÃO saia da linha. Para abrir ou fechar uma janela você deve pressionar <JOYPAD:AButton,28,28>. Para pulá-la você deve pressionar <JOYPAD:BButton,28,28> . <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:AButton,28,28> para reabrir a janela, antes de considerarmos o término dessa etapa de aprendizado.",
    IGUI_Tutorial1_Fight4Joypad = " <SIZE:medium> Ela não nos viu! <LINE> <LINE> Movendo o <JOYPAD:RStick,28,28> em qualquer direção preparará sua arma para um ataque. <LINE> <LINE> <SIZE:large> Mova o <JOYPAD:RStick,28,28> !",
    IGUI_Tutorial1_Fight5Joypad = " <SIZE:medium> Mova o <JOYPAD:RStick,28,28> em direção ao zumbi, e caminhe usando o <JOYPAD:LStick,28,28> para chegar perto! <LINE> <LINE> Pressione <JOYPAD:RTrigger,28,28> para atacar quando estiver pronto!",
    IGUI_Tutorial1_Fight7Joypad = " <SIZE:medium> Toma essa Mamãe! <LINE> <LINE> Você também poderia ter pressionado <JOYPAD:LTrigger,28,28> para empurrá-la, mas agora precisamos acertar a cabeça! <LINE> <LINE> Alinhe-se usando <JOYPAD:LStick,28,28> e <JOYPAD:RStick,28,28> e bata nela usando <JOYPAD:RTrigger,28,28>.",
    IGUI_Tutorial1_Fight8NewJoypad = " <SIZE:medium> A Frigideira quebrou! O crânio da sua mãe era muito resistente! <LINE> <LINE> <SIZE:medium> Vamos pegar emprestada a Faca de Caça que enfiamos nas costas dela antes! Equipe na Mão Principal! <LINE> <LINE> <SIZE:large> Abra o Painel de Loot usando <JOYPAD:YButton,28,28> , então selecione a Faca de Caça e pressione <JOYPAD:AButton,28,28> para mostrar as opções de Equipamento!",
    IGUI_Tutorial1_Sneak1Joypad = " <SIZE:medium> Você ouviu isso? Tem mais! <LINE> <LINE> Mova-se até o portão na cerca alta! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:AButton,28,28> para abrir o portão quando estiver perto!",
    IGUI_Tutorial1_Sneak1BisJoypad = " <SIZE:medium> Morto-vivo vegetativo na horta! Mas ele tem função cerebral suficiente para ver você! <LINE> <LINE> Se você for furtivo, fará menos barulho, e será menos visível. <LINE> <LINE> <SIZE:large> Mova para baixo <JOYPAD:LStick,28,28> para agachar e mova-se furtivamente!",
    IGUI_Tutorial1_Sneak2BisJoypad = " <SIZE:medium> Faça como solicitamos. Isso é perder tempo e dinheiro. <LINE> <LINE> Mova para baixo <JOYPAD:LStick,28,28> para agachar. Fique perto da cerca para se agachar automaticamente. <LINE> <LINE> <SIZE:large> Mova-se furtivamente para o portão na cerca. Agora.",
    IGUI_Tutorial1_Sneak3Joypad = " <SIZE:medium> Tão silencioso e tão mortal! Como um ninja condenado! <LINE> <LINE> <SIZE:large> Fique agachado e abra o portão com <JOYPAD:AButton,28,28> quando estiver perto!",
    IGUI_Tutorial1_Sneak4Joypad = " <SIZE:medium> Isso aqui é coisa de Forças Especiais! <LINE> <LINE> Caminhe atrás dele com a faca! Seu braço irá levantar para mostrar que você está pronto para um ataque furtivo! <LINE> <SIZE:large> Aproxime-se com <JOYPAD:RStick,28,28> e <JOYPAD:LStick,28,28> , ataque com <JOYPAD:RTrigger,28,28> quando estiver diretamente atrás! Chegue perto com calma! ",
    IGUI_Tutorial1_Sneak4BisJoypad = " <SIZE:medium> Boa tentativa, mas você precisa se aproximar! Quando estiver ao alcance, seu braço esquerdo se levantará! <LINE> <LINE> <SIZE:large> Aproxime-se com <JOYPAD:RStick,28,28> e <JOYPAD:LStick,28,28> , ataque com <JOYPAD:LTrigger,28,28> quando estiver diretamente atrás!",
    IGUI_Tutorial1_Sneak5Joypad = " <SIZE:medium> Você conseguiu! Chega de problemas com o Papai! Agora pegue a mochila dele e coloque-a em você. <LINE> <LINE> <SIZE:large> Certifique-se de estar sobre o cadáver, pressione <JOYPAD:YButton,28,28> para lootear e pressione <JOYPAD:AButton,28,28> na Mochila Grande. Então equipe-a!",
    IGUI_Tutorial1_Sneak6Joypad = " <SIZE:medium> Você queria esta Mochila Grande há anos, e agora ela é sua! <LINE> <LINE> Vamos ver o que tem dentro! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:LBumper,28,28> para alternar entre os equipamentos.",
    IGUI_Tutorial1_Sneak7Joypad = " <SIZE:medium> Uma espingarda carregada e algumas bandagens! <LINE> Sempre fazemos o nosso melhor por você. Equipe-a com as duas mãos! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:DPadLeft,28,28> para selecionar seu inventário e pressione <JOYPAD:AButton,28,28> na espingarda para mostrar as opções de interação.",
    IGUI_Tutorial1_Bandage1Joypad = " <SIZE:medium> A janela da oficina do Papai quebrou, bem na hora! <LINE> Salte a cerca e vamos dar uma olhada! Correr para a cerca fará você saltá-la automaticamente. <LINE> <LINE> <SIZE:large> Corra usando <JOYPAD:RTrigger,28,28> e <JOYPAD:LStick,28,28> em direção à cerca!",
    IGUI_Tutorial1_Bandage2Joypad = " <SIZE:medium> Papai era um sobrevivencialista, mas ele não se preparou para você, não é mesmo? <LINE> <LINE> Vamos lootear sua oficina! Ignore os cacos de vidro! <LINE> <LINE> <SIZE:large> Pule pela janela quebrada ficando próximo a ela e pressionando <JOYPAD:BButton,28,28>.",
    IGUI_Tutorial1_Bandage2BisJoypad = " <SIZE:medium> INSOLÊNCIA! Essa NÃO era a cerca que dissemos para você saltar! <LINE> <LINE> Vamos continuar, de qualquer maneira. Há uma janela quebrada no galpão além da horta. <LINE> <LINE> <SIZE:large> Pule-a pressionando <JOYPAD:BButton,28,28>.",
    IGUI_Tutorial1_Bandage3Joypad = " <SIZE:medium> Ah não! Suas mãos estão sangrando! O vidro quebrado na janela as cortaram. Quem poderia imaginar? <LINE> <LINE> <SIZE:large> Abra o Painel de Saúde segurando <JOYPAD:Back,28,28> e  selecione o Ícone de Coração com <JOYPAD:RStick,28,28>.",
    IGUI_Tutorial1_Bandage4Joypad = " <SIZE:medium> As bandagens da mochila vão ajudar! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:AButton,28,28> e aplique um curativo.",
    IGUI_Tutorial1_Bandage6Joypad = " <SIZE:medium> As cortinas impedem que você veja para fora, mas também impedem que a horda veja <JOYPAD:RTrigger,28,28>para dentro! <LINE> <LINE> Abra a cortina, provavelmente é seguro. <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:XButton,28,28> para interagir e abrir a cortina.",
    IGUI_Tutorial1_Shotgun1Joypad = " <SIZE:medium> Lembre-se que você pode ser furtivo para fazer menos barulho. <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:LStick,28,28> para se agachar e vá até a cerca com arame.",
    IGUI_Tutorial1_Shotgun1bJoypad = " <SIZE:medium> Se você tem habilidade o suficiente, e não estiver cansado, cercas altas podem ser escaladas! <LINE> <LINE> <SIZE:large> Você tem essa habilidade! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:BButton,28,28> para pular a cerca de arame! ",
    IGUI_Tutorial1_Shotgun2Joypad = " <SIZE:medium> Tão atlético! É hora de fazer barulho! <LINE> <LINE> Prepare a espingarda! <LINE> <LINE> <SIZE:large> Mire nos mortos-vivos segurando <JOYPAD:RStick,28,28>.",
    IGUI_Tutorial1_Shotgun3Joypad = " <SIZE:medium> Aí vem eles! <LINE> <LINE> <GHC> Um contorno verde mostra uma boa chance de sucesso com o alvo! <RGB:1,1,1> <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:RTrigger,28,28> para disparar enquanto mira segurando <JOYPAD:RStick,28,28>.",
    IGUI_Tutorial1_Shotgun4Joypad = " <SIZE:medium> Estão todos mortos! Que pena! Não importa, logo vocês estarão juntos novamente! <LINE> <LINE> Cada zumbi na floresta ouviu a espingarda, e eles estão vindo atrás de você! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:BButton,28,28> para pular a cerca de arame e escapar! ",
    IGUI_Tutorial1_Shotgun5Joypad = " <SIZE:medium> Eles estão se aproximando! <LINE> <LINE> Você sabe como correr, mas agora aprenderá como CORRER MAIS RÁPIDO! Corra depressa para o marcador perto da casinha! Agora! <LINE> <LINE> <SIZE:large> Pressione <JOYPAD:RTrigger,28,28> enquanto se move para correr, então pressione <JOYPAD:BButton,28,28> para correr ainda mais! ",
    IGUI_Tutorial1_Shotgun6Joypad = " <SIZE:medium> Último conselho! Nunca grite. Lembra do seu condicionamento? A palavra chave é... Spiffo.",
    IGUI_Tutorial1_Shotgun7Joypad = " <SIZE:medium> Excelente! Morra bem!",
    IGUI_Tutorial1_Shotgun8Joypad = " <CENTRE> <SIZE:medium> Você morreu! <LINE> <LINE> <SIZE:large> Retorne ao Menu Principal e sobreviva ao verdadeiro Evento de Knox!",
