    IGUI_InfoPanel_Inventory = "<CENTRE> <SIZE:large> Bem-vindo ao Project Zomboid! <LINE> <LINE> <SIZE:medium>Em breve, você morrerá horrivelmente. Ninguém vai chorar por você, e você será rapidamente esquecido. Tudo terá sido em vão! <LINE> <LINE> Então vamos garantir que você saia lutando!",
