    IGUI_DesignationZone_Type_IncorrectSize = "Tamanho Inválido",
    IGUI_DesignationZone_Title = "Zonas de Rebanho Próximas",
    IGUI_Animal_NoZoneFound = "Não foi atribuída nenhuma zona. Vagará.",
    IGUI_Animal_ZoneName = "Zona de Rebanho",
    IGUI_DesignationZone_AddZone = "Criar esta zona?",
