    IGUI_DesignationZone_FeedingTroughs = "Bandeirinhas:",
    IGUI_DesignationZone_Hutchs = "Acasas de abrigo:",
    IGUI_DesignationZone_InHutch = "No estábulo",
    IGUI_DesignationZone_Food = "Alimentos disponíveis: ",
    IGUI_DesignationZone_Water = "Água disponível: ",
    IGUI_DesignationZone_RoofArea = "Área Coberta:",
    IGUI_DesignationZone_NearRiver = "Perto dos azulejos do rio: ",
    IGUI_DesignationZone_WanderInfo = "Animais não deixarão suas zonas designadas enquanto estiverem seguras.",
    IGUI_DesignationZone_WanderInfo2 = "Eles sairão se estiverem muito estressados, com sede ou se houver zumbis por perto.",
    IGUI_AnimalUI_Info_cow = "Vacum: O <LINE> vacum: <LINE> Vaca: <LINE> Os filhotes precisam de leite da mãe. <LINE> A época de reprodução ocorre o ano todo. <LINE> Vacas começam a produzir leite alguns dias após ficarem grávidas. <LINE> Você pode ordenhar uma vaca com um balde. <LINE> Quando a gravidez terminar, se não for ordenhada ou o filhote não se alimentar da mãe, a vaca parará de produzir leite após alguns dias. <LINE> Pode comer Feno, Grama, Vegetais, Frutas e Alimento Animal.",
    IGUI_AnimalUI_Info_bull = " <LINE> <LINE> Bull: <LINE> Os bezerros precisam de leite da mãe. <LINE> A temporada de acasalamento é o ano todo. <LINE> Desde a adolescência, touros lutarão contra outros touros. <LINE> Pode comer Hay, Grass, vegetais, frutas e ração animal.",
    IGUI_AnimalUI_Info_pig = " <LINE> <LINE> Porco: <LINE> Leitões precisam de leite da mãe. <LINE> Sua temporada de acasalamento é de setembro a fevereiro. <LINE> Sows começam a produzir leite alguns dias depois de engravidar. <LINE> Quando a gravidez acabar, se não for ordenhada ou um leitão não se alimentar da porca, a porca deixará de produzir leite depois de alguns dias. <LINE> Pode comer Hay, Grass, vegetais, frutas e ração animal.",
    IGUI_AnimalUI_Info_boar = " <LINE> <LINE> Boar: <LINE> Leitões precisam de leite da mãe. <LINE> Sua temporada de acasalamento é de setembro a fevereiro. <LINE> Os machos não brigam. <LINE> Pode comer Hay, Grass, vegetais, frutas e ração animal.",
    IGUI_AnimalUI_Info_ewe = "<LINE> <LINE> Ewe: Ovelha precisa de leite da sua mãe. <LINE> Cordeiros precisam de leite da sua mãe. <LINE> A época de reprodução é de setembro a fevereiro. <LINE> Ovelhas começam a produzir leite alguns dias após ficarem grávidas. <LINE> Você pode ordenhar uma ovelha com um balde. <LINE> Quando a gravidez terminar, se não for ordenhada ou um cordeiro não se alimentar da ovelha, a ovelha parará de produzir leite após alguns dias. <LINE> A ovelha começa a produzir lã a partir da adolescência. <LINE> Você pode tosar um animal que tenha lã suficiente com um Tesoura. <LINE> Pode comer Feno, Grama, Vegetais, Frutas e Alimento Animal.",
    IGUI_AnimalUI_Info_ram = " <LINE> <LINE> Bode: <LINE> Ovelhas precisam de leite da sua mãe. <LINE> A época de reprodução é de setembro a fevereiro. <LINE> A partir da adolescência, os bois lutam com outros bois. <LINE> Bois começam a produzir lã a partir da adolescência. <LINE> Você pode levar a lã de um animal que tem lã suficiente com uma tesoura. <LINE> Pode comer Feno, Grama, Vegetais, Frutas e Alimento Animal.",
    IGUI_AnimalUI_Info_hen = "<LINE> Galinha: <LINE> Galinhas entrarão em um curral à noite. Animais dentro de um curral fechado serão protegidos de predadores. <LINE> Animais sairão do curral pela manhã. <LINE> Uma galinha que foi fertilizada por um galo irá botar ovos que irão eclodir. <LINE> Uma galinha põe um ovo por dia. <LINE> Apenas uma galinha que foi fertilizada por um galo irá botar ovos que irão eclodir. <LINE> A época de reprodução é o ano todo. <LINE> Pode comer Feno, Grama, Vegetais, Frutas, Sementes, Nozes e Ração Animal.",
    IGUI_AnimalUI_Info_cockerel = " <LINE> <LINE> Cockerel: <LINE> Animais dentro da cabana fechada serão protegidos de predadores. <LINE> Os animais deixarão a cabana pela manhã. <LINE> Só uma galinha que foi fertilizada por um galo pode pôr ovos que vão eclodir. <LINE> A temporada de acasalamento é o ano todo. <LINE> Desde a adolescência, galos lutarão contra outros galos. <LINE> Pode comer feno, grama, legumes, frutas, sementes, nozes e ração animal.",
    IGUI_Hutch_Info = "<CENTRE> <SIZE:medium> Hutch <LINE> <LINE> <LEFT> <SIZE:small> As galinhas vão entrar na cabana de noite até de manhã se as portas forem abertas para permitir que elas o façam. <LINE> <LINE> Hutches se sujam com o tempo, e ficam mais sujos com mais animais lá dentro, limpam uma cabana com água e um esfregão ou toalha, uma cabana suja terá um impacto negativo na saúde de seus ocupantes. <LINE> <LINE> As galinhas colocarão ovos nas caixas de ninho dentro das cabanas.",
    IGUI_VehicleNameTrailer_Horsebox = "Trailer de cavalo",
    IGUI_VehicleNameTrailer_Livestock = "Trailer de Gado",
    IGUI_AnimalTrailer_Info = "<CENTRE> Trailer de Animais <SIZE:medium> <LINE> <LINE> <LEFT> <SIZE:small> Para colocar um animal dentro de um trailer, aproxime-o da porta traseira e clique com o botão direito no trailer. <LINE> Você também pode fazer isso com um pequeno animal que estiver carregando. <LINE> <LINE> Os animais podem comer do recipiente de comida dentro de um trailer. <LINE> Você também pode alimentar ou dar água a um animal dentro de um trailer clicando com o botão direito no trailer. <LINE> Trailers possuem uma caixa de ninho, onde galinhas irão botar ovos. <LINE> Cada trailer tem uma capacidade total, com cada animal contribuindo para essa capacidade dependendo de seu tipo e tamanho. <LINE> Animais em trailers ganharão lentamente estresse quando o trailer estiver em movimento.",
